/**
 * Fieldnote service worker — the offline shell.
 *
 * Plan §5 non-negotiable 5: capture works in a parking lot with no signal. The bar is a
 * hard reload with the network disabled, not a network toggle on an already-loaded page,
 * because the second passes with no service worker at all and proves nothing.
 *
 * Hand-written rather than generated by a plugin. The only generated part is the list of
 * URLs to precache, which cannot be hand-written because Next content-hashes its asset
 * filenames — `scripts/build-service-worker.mjs` reads them out of the build and writes
 * `public/precache.json`. Everything else is here, in one readable file.
 *
 * Two rules this file must not break, from CLAUDE.md and plan §4.1:
 *
 *   - Nothing from a third-party origin is ever cached or fetched. The handler below
 *     returns early for any cross-origin request, so they pass through untouched.
 *   - No API route is cached. Session 5's model route is the system's only egress, and a
 *     cached response to it would be a stale copy of a generation — with content in it —
 *     sitting in a cache this file would then be responsible for. The guard is written
 *     now, before the route exists, because that is the cheap moment to write it.
 *
 * KNOWN LIMITATION — this worker does not update after a deploy. `bd show fieldnote-jug`.
 * The install and activate handlers below re-prime and prune the cache correctly, but a
 * browser only re-installs a worker when the script's bytes change, and this file is
 * hand-written and identical across builds. So install runs once, ever. Verified by
 * building, loading, changing a source string, rebuilding, and reloading: the old build
 * is still what runs, online and offline. Nothing is lost and the app keeps working — it
 * is pinned to whichever build the user first loaded. The fix is to make the script vary
 * per build, and it is not in this session.
 */

/** Single cache, pruned to the precached manifest on activate. */
const CACHE_NAME = "fieldnote-shell";

/** Written by `scripts/build-service-worker.mjs` as part of `pnpm build`. */
const PRECACHE_URL = "/precache.json";

/** The navigation fallback: what an offline reload of any page is served. */
const SHELL_URL = "/";

/**
 * Populates the cache from the generated manifest.
 *
 * `addAll` is all-or-nothing on purpose. A partially populated shell fails later, in the
 * field, on the one reload that mattered; a failed install fails now and is visible in
 * DevTools as a service worker that never reached "activated".
 *
 * The manifest response is stored alongside the assets so `activate` can read the URL
 * list back without a network round trip.
 */
async function install() {
  const response = await fetch(PRECACHE_URL, { cache: "reload" });
  if (!response.ok) {
    throw new Error(`precache manifest ${PRECACHE_URL} returned ${response.status}`);
  }
  const manifest = await response.clone().json();

  const cache = await caches.open(CACHE_NAME);
  // `cache: "reload"` bypasses the HTTP cache, so a precache never captures a stale copy
  // of an asset the browser happened to be holding.
  await cache.addAll(manifest.urls.map((url) => new Request(url, { cache: "reload" })));
  await cache.put(PRECACHE_URL, response);

  await self.skipWaiting();
}

/**
 * Drops anything the current build no longer references, then takes over open pages.
 *
 * Pruning here rather than at install matters: while a new worker is installing, the old
 * one is still serving pages built against the old assets. Deleting those assets at
 * install time would pull chunks out from under a page that is still running.
 */
async function activate() {
  const cache = await caches.open(CACHE_NAME);
  const manifest = await cache.match(PRECACHE_URL);

  if (manifest) {
    const { urls } = await manifest.json();
    const keep = new Set(
      [...urls, PRECACHE_URL].map((url) => new URL(url, self.location.origin).href),
    );
    const cached = await cache.keys();
    await Promise.all(
      cached
        .filter((request) => !keep.has(request.url))
        .map((request) => cache.delete(request)),
    );
  }

  await self.clients.claim();
}

/**
 * Navigations: network first, cached shell on failure.
 *
 * Network first because a local-first app still wants the newest shell when there is a
 * signal, and the fallback is what makes the offline reload work. The fallback is the
 * cached `/` document for every navigation, not just `/` — there is one route today, and
 * serving the shell is the right answer for a client-rendered app regardless.
 */
async function handleNavigation(request) {
  try {
    return await fetch(request);
  } catch (offline) {
    const shell = await caches.match(SHELL_URL);
    if (shell) return shell;
    throw offline;
  }
}

/** Content-hashed build assets. The name changes when the bytes change, so never revalidate. */
async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;

  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(CACHE_NAME);
    await cache.put(request, response.clone());
  }
  return response;
}

/**
 * Everything else same-origin: network, falling back to whatever was precached.
 *
 * Deliberately does not populate the cache. Caching arbitrary responses here would grow
 * the cache without bound and without a rule saying what is in it, and the precache
 * manifest is meant to be the complete answer to "what does offline hold".
 */
async function networkFirst(request) {
  try {
    return await fetch(request);
  } catch (offline) {
    const cached = await caches.match(request);
    if (cached) return cached;
    throw offline;
  }
}

self.addEventListener("install", (event) => {
  event.waitUntil(install());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(activate());
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Third-party origins are not this worker's business. Plan §4.1: the model API route is
  // the only egress, and nothing off-origin is cached, precached, or proxied here.
  if (url.origin !== self.location.origin) return;

  // Session 5's model route. Never cached — see the header of this file.
  if (url.pathname.startsWith("/api/")) return;

  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(request));
    return;
  }

  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request));
    return;
  }

  event.respondWith(networkFirst(request));
});
